CREATE POLICY profiles_admin_read ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.lms_validate_device_session() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NEW.session_id IS DISTINCT FROM auth.jwt()->>'session_id' THEN RAISE EXCEPTION 'Device session does not match your sign-in'; END IF; RETURN NEW; END $$; CREATE TRIGGER device_session_validation BEFORE INSERT ON public.registered_devices FOR EACH ROW EXECUTE FUNCTION public.lms_validate_device_session();
CREATE FUNCTION public.lms_validate_receipt() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='payment-receipts' AND name=NEW.receipt_path AND (storage.foldername(name))[1]=NEW.user_id::text AND COALESCE((metadata->>'size')::bigint,0)>0 AND COALESCE((metadata->>'size')::bigint,0)<=10485760 AND metadata->>'mimetype' IN ('image/png','image/jpeg','application/pdf')) THEN RAISE EXCEPTION 'A valid private receipt is required'; END IF; RETURN NEW; END $$; CREATE TRIGGER order_receipt_validation BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.lms_validate_receipt();